def bubble_sort_0(items: list[int]) -> list[int]:
    n = len(items)
    res = list(items)
    for i in range(n):
        for j in range(0, n - i - 1):
            if res[j] > res[j + 1]:
                res[j], res[j + 1] = res[j + 1], res[j]
    return res

