def find_median_0(numbers: list[float]) -> float:
    if not numbers:
        return 0.0
    s = sorted(numbers)
    mid = len(s) // 2
    if len(s) % 2 == 0:
        return (s[mid - 1] + s[mid]) / 2.0
    return float(s[mid])

